#!/usr/bin/env python3
# luxarch:luxpm-close-tracks-deferrals hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a close summary that defers work without naming the issue that tracks it.

PreToolUse(luxpm_update_issue, luxpm_create_issue): every `close_summary` the call writes (the
single form, each `updates[]` entry, a create filed as done) is read sentence by sentence. A
sentence that defers work ("not built", "deferred", "follow-up", "out of scope", "stated limit",
"next release", "UNREPRODUCED", …) must name another issue's key (`<ticket>`) or say `dropped`
with its reason. A lead-in that defers ("**Not built:**") hands that duty to each bullet under it,
and a deferring sentence may hand it to the next one ("Not built: X. That's AB-12."). Words inside a
code span with no space (`[rules.deferred]`) and luxarch's own `0 xfail (deferred)` are a name, not
prose, and a `Follow-up (<sha>):` names the commit that shipped it.

A sentence that says nothing remains defers nothing, when the WHOLE sentence is made of the fixed
words of one of those forms: "Nothing deferred.", "No follow-ups.", "No follow-up needed.", "No stated
limits remain.", "Follow-ups: none.", "The open question is answered.". No form has a free-text
slot, since each such slot (a subject, a reason after a colon, trailing items) is where remaining
work rode through. A form inside a longer sentence clears nothing ("Nothing deferred aside from the
Windows port." is read as it always was), and a hurried "No time for follow-up." is denied.

`--scan FILE` reads a JSON object of `{"<KEY>": "<close summary>"}` and prints each untracked
deferral as `<KEY>: <sentence>`, exiting 1 when there is one: `/luxpm-audit` runs it over a project's
closed summaries.

**Why a hook.** A close summary lives on a closed issue, and a closed issue is in no open list,
no focus digest and no backlog sweep: work written only there is tracked by nothing. `/wrap-up`
said "every finding filed or dropped" in text, and an agent still wrote "Not built: …" twice into
a close summary and called it filed. The rule's home is `/wrap-up` step 6 ("A close summary is not
a tracker"); this makes it hold.

It reads only the text the call carries, so it cannot tell whether the cited key is open: citing
one is the agent's statement that it is, and the key is there for anyone to check. Fails OPEN on
input it cannot read: a hook that blocks on its own uncertainty gets switched off.
"""

from __future__ import annotations

import json
import re
import sys

_DEFERS = re.compile(
    r"\b(?:not\s+(?:yet\s+)?(?:built|done|fixed|implemented|handled|covered|shipped|filed|tracked"
    r"|verified|confirmed|checked|tested|run|taken|asked)"
    r"|did\s+not\s+(?:build|do|fix|ship|verify|check)|unconfirmed|unverified|untested"
    r"|open\s+(?:owner\s+)?questions?|left\s+in\s+place"
    r"|deferred|defer(?:s|ring)?\b|follow[- ]?ups?\b"
    r"|a\s+future\s+(?:tightening|rule|check|release|cut|pass|version|change)"
    r"|out\s+of\s+scope|(?:stated|known)\s+(?:limits?|limitations?)\b"
    r"|left\s+(?:for|as\s+is|open)|for\s+later|(?:a|in\s+a)\s+later\s+(?:cut|release|pass|version)"
    r"|next\s+(?:release|cut|pass)|todo\b|unreproduced|not\s+reproduced"
    r"|still\s+(?:open|to\s+do|missing)|remains?\s+(?:open|to\s+(?:do|be))|(?:filed|tracked|handled)\s+separately)",
    re.IGNORECASE,
)
_KEY = re.compile(r"\b[A-Z][A-Z0-9]{1,15}-\d+\b")
_DROPPED = re.compile(r"\bdropped\b", re.IGNORECASE)
_BULLET = re.compile(r"^\s*(?:[-*+]|\d+[.)])\s+")
_SENTENCE = re.compile(r"(?<=[.!?])\s+(?=[A-Z*`(\"'])")
# A code span with no space is a name, not prose (`[rules.deferred]`), and so is luxarch's own
# summary count `0 xfail (deferred)` (a count above 0 is deferred tests, and reads as such).
_CODE = re.compile(r"`[^`\s]+`|\b0\s+xfail\s+\(deferred\)", re.IGNORECASE)
_HEX = r"(?=[0-9a-f]*[a-f])(?=[0-9a-f]*[0-9])[0-9a-f]{7,40}"
# A follow-up that names the commit that shipped it: `Follow-up (<sha>)`.
_SHIPPED = re.compile(rf"follow[- ]?ups?\s*\([^)]*\b{_HEX}\b[^)]*\)", re.IGNORECASE)
_FOLLOW_UP = r"follow[- ]?ups?"
_REMAINDER = (
    rf"(?:{_FOLLOW_UP}|deferrals?|deferred\s+work|(?:stated|known)\s+limit(?:ation)?s?"
    r"|open\s+questions?)"
)
_NEEDED = r"(?:needed|required|remains?|remaining|left)"
_SHIPPED_ALL = r"(?:full\s+scope|everything|all\s+of\s+it|all)\s+shipped"
_JOIN = r"\s*[,;—–-]\s*"
# The sentences that say nothing remains, made of FIXED words only, and only as the WHOLE sentence.
# No slot takes free text, so no wording of remaining work can ride inside one: every form a past
# attack used for that (a free subject, a reason after a colon, trailing items) is not read here.
_NOTHING_LEFT = re.compile(
    rf"(?:{_SHIPPED_ALL}{_JOIN})?"
    r"(?:"
    r"(?:nothing|none)\s+(?:(?:is|was|has\s+been)\s+)?(?:being\s+)?(?:left\s+)?deferred"
    r"|nothing\s+was\s+deferred\s+and\s+nothing\s+is\s+left\s+open"
    rf"|no\s+(?:(?:further|new|additional|remaining|outstanding)\s+)?{_REMAINDER}(?:\s+work)?"
    rf"(?:\s+(?:or|and)\s+{_REMAINDER})?(?:\s+(?:(?:is|are|was|were)\s+)?{_NEEDED})?"
    rf"|there\s+(?:is|are)\s+no\s+{_REMAINDER}(?:\s+{_NEEDED})?"
    rf"|(?:{_REMAINDER}|deferred|not\s+built)\s*(?::|—|–|-)\s*(?:none|nothing|n/a)"
    r"(?:\s+(?:needed|required))?"
    rf"|{_REMAINDER}\s+(?:(?:is|are)\s+)?not\s+(?:needed|required)"
    r"|(?:(?:i|we)\s+)?(?:did\s+not|didn't)\s+defer\s+anything"
    rf"|(?:(?:i|we)\s+)?(?:will\s+not|won't)\s+need\s+an?\s+{_FOLLOW_UP}"
    r"|(?:the|all|every)\s+open\s+questions?(?:\s+on\s+this\s+(?:ticket|issue))?\s+"
    r"(?:(?:is|are|was|were)\s+)?(?:(?:therefore|now|all|already)\s+)?(?:answered|resolved|settled)"
    r")"
    rf"(?:{_JOIN}{_SHIPPED_ALL})?\s*[.!]?",
    re.IGNORECASE,
)
_POINTER = re.compile(r"^(?:That|This|It|Tracked|Filed)\b")


def _says_nothing_left(text: str) -> bool:
    """The whole sentence (a bullet's text, bold and curly apostrophes aside) is one of the fixed
    forms that say nothing remains."""
    s = text.replace("’", "'").replace("*", "").strip()
    return bool(_NOTHING_LEFT.fullmatch(_BULLET.sub("", s).strip()))


def _defers(text: str) -> bool:
    if _says_nothing_left(text):
        return False
    return bool(_DEFERS.search(_SHIPPED.sub("", _CODE.sub("``", text))))


def _own_key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _tracked(text: str, own: str) -> bool:
    return bool(_DROPPED.search(text)) or any(k != own for k in _KEY.findall(text))


def untracked(summary: str, own: str) -> list[str]:
    """Each sentence (or bullet under a deferring lead-in) that defers work and names no other
    issue and no `dropped`."""
    out: list[str] = []
    lines = summary.splitlines()
    k = 0
    while k < len(lines):
        line = lines[k]
        k += 1
        plain = line.strip().strip("*_ ").rstrip("*_ ")
        if not plain:
            continue
        if _defers(plain) and plain.endswith(":") and not _tracked(plain, own):
            # a lead-in: each bullet under it (until a blank line or a non-bullet) carries the duty
            under = False
            while k < len(lines) and (
                _BULLET.match(lines[k]) or (under and lines[k].startswith((" ", "\t")))
            ):
                if _BULLET.match(lines[k]):
                    under = True
                    if not _tracked(lines[k], own):
                        out.append(lines[k].strip())
                k += 1
            if not under:
                out.append(plain)
            continue
        sentences = _SENTENCE.split(plain)
        for i, sentence in enumerate(sentences):
            nxt = sentences[i + 1] if i + 1 < len(sentences) else ""
            handed = bool(_POINTER.match(nxt)) and _tracked(nxt, own)
            if _defers(sentence) and not _tracked(sentence, own) and not handed:
                out.append(sentence.strip())
    return out


def _closes(tool_input: dict[str, object]) -> list[tuple[str, str]]:
    entries: list[dict[str, object]] = [tool_input]
    updates = tool_input.get("updates")
    if isinstance(updates, list):
        entries += [u for u in updates if isinstance(u, dict)]
    project = tool_input.get("project")
    out: list[tuple[str, str]] = []
    for e in entries:
        summary = e.get("close_summary")
        if isinstance(summary, str) and summary.strip():
            out.append((_own_key(e, project), summary))
    return out


def scan(path: str) -> int:
    with open(path, encoding="utf-8") as f:
        summaries = json.load(f)
    found = [
        f"{key}: {s}"
        for key, summary in summaries.items()
        for s in untracked(str(summary), str(key).upper())
    ]
    print("\n".join(found) if found else "no untracked deferrals")
    return 1 if found else 0


def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] == "--scan":
        return scan(sys.argv[2])
    try:
        ev = json.load(sys.stdin) or {}
        ti = ev.get("tool_input")
        closes = _closes(ti if isinstance(ti, dict) else {})
    except Exception:
        return 0  # hooks fail OPEN
    found = [(own, s) for own, summary in closes for s in untracked(summary, own)]
    if not found:
        return 0
    lines = "\n".join(f"  - {own or 'this issue'}: {s[:200]}" for own, s in found)
    print(
        "DENIED: this close summary defers work that no open issue tracks. A closed issue is in no "
        "open list, focus or backlog sweep, so work written only into its summary is lost:\n"
        f"{lines}\n"
        "For each: search LuxPM, then file it as its own open issue (or comment on the open one "
        "that covers it) and name that key in the sentence, e.g. `Not built: X (<ticket>)`. "
        "Work you decided against says `dropped: <why>` instead. Then close again. "
        'See /wrap-up step 6, "A close summary is not a tracker".',
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    sys.exit(main())
